uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float width : 0.01 .. 0.5 = 0.10;
uniform vec3 tint : color = 1.0, 0.8, 0.2;

state float phase;

void update() {
  phase = fract(phase + dt * speed * 0.5);
}

vec3 shade(Led led) {
  fixed x = fixed(led.pos.x);
  fixed p = fixed(phase);
  fixed d = abs(x - p);
  fixed band = clamp(fixed(1.0) - d * fixed(1.0) / fixed(width), fixed(0.0), fixed(1.0));
  return hsv2rgb(fixed(0.08), fixed(1.0), band) * vec3(tint.r, tint.g, tint.b);
}

uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float width : 0.01 .. 0.5 = 0.10;
uniform vec3 tint : color = 1.0, 0.8, 0.2;

state float phase;

void update() {
  phase = fract(phase + dt * speed * 0.5);
}

vec3 shade(Led led) {
  fixed x = fixed(led.pos.x);
  fixed p = fixed(phase);
  fixed d = abs(x - p);
  fixed band = clamp(fixed(1.0) - d / fixed(width), fixed(0.0), fixed(1.0));
  vec3 c = hsv2rgb(fixed(0.08), fixed(1.0), band);
  return vec3(c.r * fixed(tint.r), c.g * fixed(tint.g), c.b * fixed(tint.b));
}

uniform float speed : 0.0 .. 5.0 = 1.0;
